// @ts-check

// This runs in Node.js - Don't use client-side code here (browser APIs, JSX...)

/**
 * AutoDocs wires this sidebar from docs/_sidebar.autodocs.json (written by
 * generate-product-docs.mjs) instead of Docusaurus's default folder-based
 * autogeneration: product pages pinned first, then any docs.sections
 * groupings, then every other tour flat. Read fresh at build time (not
 * cached across builds) so a later /document run's regeneration is picked
 * up on the site's next build with no edit needed here.
 *
 * docs/archive/ still needs its own autogenerated entry explicitly: the
 * default {type: 'autogenerated', dirName: '.'} sidebar recurses into every
 * subfolder for free, but this explicit array doesn't unless told to — an
 * archived tour would otherwise silently drop out of the sidebar nav (it'd
 * still build and be reachable by direct URL/search, just invisible here).
 */
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const sidebarDataPath = path.join(__dirname, '..', 'docs', '_sidebar.autodocs.json');
const archiveDir = path.join(__dirname, '..', 'docs', 'archive');

function buildGeneratedSidebar() {
  if (!fs.existsSync(sidebarDataPath)) {
    // No product/tour docs generated yet — nothing to build a real sidebar
    // from. Falls back to the scaffolded default; re-running
    // `/autodocs:document init-site` once docs exist picks this up.
    return [{ type: 'autogenerated', dirName: '.' }];
  }

  const data = JSON.parse(fs.readFileSync(sidebarDataPath, 'utf8'));

  const items = [
    ...data.productPages,
    ...data.sections.map((section) => ({
      type: 'category',
      label: section.label,
      items: section.tours,
    })),
    ...data.unsectionedTours,
  ];

  if (fs.existsSync(archiveDir)) {
    items.push({
      type: 'category',
      label: 'Archive',
      items: [{ type: 'autogenerated', dirName: 'archive' }],
    });
  }

  return items;
}

/** @type {import('@docusaurus/plugin-content-docs').SidebarsConfig} */
const sidebars = {
  tutorialSidebar: buildGeneratedSidebar(),
};

export default sidebars;
